export function getRuleLevel(ruleConfig, rule) {
    const level = Array.isArray(ruleConfig) ? ruleConfig[0] : ruleConfig;
    if (level == null) {
        return 0;
    }
    let levelNum = _.isNumber(level) ? level : _.toNumber(level);
